def _get(name: str):
    for n, d, m in EXPECTED:
        if n == name:
            return d, m
    raise ValueError("missing " + name)

def check(name: str, r):
    d, m = _get(name)
    fd = r.filled(0).ravel()
    fm = ma.getmaskarray(r).ravel()
    ok = fd.size == len(d)
    if ok:
        for i in range(len(d)):
            if abs(float(fd[i]) - d[i]) > 1e-9 * (1. + abs(d[i])):
                ok = False
    if len(m) > 0:
        if fm.size != len(m):
            ok = False
        else:
            for i in range(len(m)):
                if fm[i] != m[i]:
                    ok = False
    if not ok:
        print("TEST FAILED:", name, r, d, m)

def check_plain(name: str, a):
    d, m = _get(name)
    fa = np.asarray(a).ravel()
    ok = fa.size == len(d)
    if ok:
        for i in range(len(d)):
            if abs(float(fa[i]) - d[i]) > 1e-9 * (1. + abs(d[i])):
                ok = False
    if not ok:
        print("TEST FAILED:", name, a, d)

def check_mask(name: str, r):
    d, m = _get(name)
    fm = ma.getmaskarray(r).ravel()
    ok = fm.size == len(m)
    if ok:
        for i in range(len(m)):
            if fm[i] != m[i]:
                ok = False
    if not ok:
        print("TEST FAILED:", name, r, m)

def eqs(name: str, got: str, want: str):
    if got != want:
        print("TEST FAILED:", name)
        print(got)
        print(want)

